cd /Users/nikolaydidiletsov/Documents/Codex/MUCHackatonFinal/agent/arena_kit/sim_cases; python3 - <<'E'
import json,glob,re,collections
c=collections.Counter()
for f in sorted(glob.glob('real_runs/*_P*.json')):
    d=json.load(open(f))
    for s,t in d['threads'].items():
        for i,m in enumerate(t['messages']):
            if m['from']=='buyer': continue
            b=m.get('body') or ''
            for q in re.findall(r'[^.!?\n]*\?',b): print(f.split('/')[1][:-5],i,'|',q.strip()[:160])
            for k in ('absolute limit','data behind','breakdown','send us','strictly tied','allocation cap','notice period','standard Zahlungsziel'):
                if k.lower() in b.lower(): c[(f.split('/')[1].split('_P')[1][:2],s,k)]+=1
print(sorted(c.items()))
E

